mapper.select:
SELECT wmrs.id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, db.name AS moduleStatusName FROM work_menu wm LEFT JOIN work_menu_ref_status wmrs ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value"
AND wm.sys_classify = #{sysClassify}
ORDER BY wm.sys_classify,wm.id

SELECT max(wmrs.id) id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, '' AS moduleStatusName FROM work_menu wm LEFT JOIN work_menu_ref_status wmrs ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value"
AND wm.sys_classify = #{sysClassify}
GROUP BY wm.sys_classify, wm.module_classify ORDER BY sys_classify,max(wmrs.id)

SELECT wo.id, wmrs.id AS moduleStatusId, wm.id AS menu_id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, wm.module_code AS moduleCode, db.name AS moduleStatusName, wmrs.module_status AS moduleStatus, wmrs.module_url AS moduleUrl, wmrs.module_param AS moduleParam FROM work_option wo LEFT JOIN work_menu_ref_status wmrs ON wo.work_menu_id = wmrs.id LEFT JOIN work_menu wm ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" WHERE wo.is_deleted = FALSE AND wo.type = '1' AND wm.module_code NOT IN ('qc_info')
AND wo.option_user_id = #{optionUserId}
ORDER BY wm.sys_classify,wm.id

SELECT wo.id, wmrs.id AS moduleStatusId, wm.sys_classify AS sysClassify, wm.id AS menu_id, wm.module_classify AS name, wmrs.module_url AS moduleUrl, wmrs.module_param AS moduleParam FROM work_option wo LEFT JOIN work_menu_ref_status wmrs ON wo.work_menu_id = wmrs.id LEFT JOIN work_menu wm ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" WHERE wo.is_deleted = FALSE AND wo.type = '2'
AND wo.option_user_id = #{optionUserId}
ORDER BY wm.sys_classify,wm.id

SELECT wm.module_classify AS source, pm.business_code AS sourceCode, pm.business_key, pm.create_user_id, EXTRACT(EPOCH FROM (pm.end_time - pm.start_time)) AS approveDuration, pm.create_time, pm.approve_status FROM process_management pm LEFT JOIN process_task_management ptm ON pm.process_instance_id = ptm.process_instance_id LEFT JOIN work_menu wm ON pm.business_key = wm.module_code WHERE 1 = 1
AND pm.approve_status = 'approveIng' AND ptm.cur_approve_id = #{params.userId}
AND pm.approve_status = 'approve' AND ptm.cur_approve_id = #{params.userId}
AND 1 <> 1
AND ptm.cur_approve_id = #{params.userId}
AND wm.sys_classify = #{params.sysClassify}
AND pm.business_code = concat('%',#{params.sysClassify},'%')
